text:
Why Choose a Beta Prior for the Movies?
The Beta distribution can represent those three beliefs. Because \(p\) is a proportion, it must lie between 0 and 1. We therefore need a prior distribution with the same possible values.
The Beta distribution is a convenient choice:
\[
p \sim \text{Beta}(\alpha, \beta)
\]
Its density is:
\[
f(p) = \frac{1}{B(\alpha, \beta)} p^{\alpha - 1}(1 - p)^{\beta - 1}, \quad 0 &lt; p &lt; 1
\]
The term \(B(\alpha, \beta)\) is a normalizing constant. It ensures that the total area under the prior density equals one.
The Beta distribution is useful for two reasons.
First, it is flexible. Depending on \(\alpha\) and \(\beta\), it can favor:

low values of \(p\),
high values of \(p\),
values near 0.50,

or every value equally.
Second, the Beta distribution is conjugate to the Binomial likelihood. Conjugacy means that a Beta prior combined with a Binomial likelihood produces a Beta posterior. The family of the distribution stays the same, although its parameters change.
This makes the update mathematically simple and visually intuitive.
Match each curve to a description, then show the answers. The curves are drawn on the same density scale.


viewof showAnswers = Inputs.toggle({
  label: "Show the answers",
  value: false
})







viewof guessA = Inputs.select(
  ["Choose one", "Uncertain", "Expects a low pass rate", "Strongly expects a high pass rate"],
  {label: "Curve A", value: "Choose one"}
)







viewof guessB = Inputs.select(
  ["Choose one", "Uncertain", "Expects a low pass rate", "Strongly expects a high pass rate"],
  {label: "Curve B", value: "Choose one"}
)







viewof guessC = Inputs.select(
  ["Choose one", "Uncertain", "Expects a low pass rate", "Strongly expects a high pass rate"],
  {label: "Curve C", value: "Choose one"}
)







// Three unlabeled Beta priors on a shared density scale
{
  // f(x) = x^(a-1) * (1-x)^(b-1) / B(a, b),
  // with B(a, b) = Γ(a)Γ(b) / Γ(a+b) computed on the log scale.
  function logGamma(z) {
    const c = [
      0.99999999999980993,
      676.5203681218851,
      -1259.1392167224028,
      771.32342877765313,
      -176.61502916214059,
      12.507343278686905,
      -0.13857109526572012,
      9.9843695780195716e-6,
      1.5056327351493116e-7
    ];
    if (z &lt; 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - logGamma(1 - z);
    z -= 1;
    let x = c[0];
    for (let i = 1; i &lt; c.length; i++) x += c[i] / (z + i);
    const t = z + 7.5;
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  }

  function betaDensity(x, a, b) {
    if (!(x &gt; 0 && x &lt; 1)) return 0;
    const logB = logGamma(a) + logGamma(b) - logGamma(a + b);
    const density = Math.exp((a - 1) * Math.log(x) + (b - 1) * Math.log(1 - x) - logB);
    return Number.isFinite(density) ? density : 0;
  }

  function betaCurve(a, b) {
    return Array.from({length: 201}, (_, i) =&gt; {
      const p = i / 200;
      const x = Math.min(1 - 1e-6, Math.max(1e-6, p));
      return {p, density: betaDensity(x, a, b)};
    });
  }

  const cards = [
    {name: "A", answer: "Strongly expects a high pass rate", alpha: 10, beta: 2, guess: guessA},
    {name: "B", answer: "Expects a low pass rate", alpha: 2, beta: 8, guess: guessB},
    {name: "C", answer: "Uncertain", alpha: 1, beta: 1, guess: guessC}
  ];
  const curves = cards.map(card =&gt; betaCurve(card.alpha, card.beta));
  const yMax = Math.max(...curves.flatMap(curve =&gt; curve.map(d =&gt; d.density)));
  const stacked = width &lt; 720;
  const plotWidth = stacked ? Math.max(260, width - 8) : Math.max(160, Math.floor((width - 32) / 3));

  const plots = cards.map((card, i) =&gt; {
    const plot = Plot.plot({
      width: plotWidth,
      height: 240,
      marginTop: 12,
      marginRight: 12,
      marginBottom: 40,
      marginLeft: 36,
      x: {label: "p", domain: [0, 1], ticks: [0, 0.5, 1]},
      y: {label: null, domain: [0, yMax * 1.08], grid: true, ticks: 4},
      marks: [
        Plot.areaY(curves[i], {x: "p", y: "density", fill: "#2c3140", fillOpacity: 0.12, curve: "linear"}),
        Plot.line(curves[i], {x: "p", y: "density", stroke: "#2c3140", strokeWidth: 2.25}),
        Plot.ruleY([0])
      ],
      style: {
        background: "transparent",
        color: "#15151E",
        fontFamily: "Helvetica, sans-serif",
        fontSize: "12px"
      }
    });
    const title = showAnswers ? card.answer : `Curve ${card.name}`;
    const note = !showAnswers
      ? ""
      : card.guess === card.answer
        ? `Beta(${card.alpha}, ${card.beta}). That match is right.`
        : card.guess === "Choose one"
          ? `Beta(${card.alpha}, ${card.beta}).`
          : `Beta(${card.alpha}, ${card.beta}). That match is not the one for this curve.`;
    return html`&lt;div class="beta-card"&gt;
      &lt;p class="card-title"&gt;${title}&lt;/p&gt;
      ${plot}
      &lt;p class="binomial-readout"&gt;${note}&lt;/p&gt;
    &lt;/div&gt;`;
  });

  return html`&lt;div class="binomial-figure"&gt;
    &lt;p class="binomial-ylabel"&gt;Density&lt;/p&gt;
    &lt;div class="beta-gallery" style="grid-template-columns: ${stacked ? "1fr" : "repeat(3, minmax(0, 1fr))"};"&gt;
      ${plots}
    &lt;/div&gt;
  &lt;/div&gt;`;
}

The Likelihood: What Does the Sample Support?
Under the Binomial model, the probability of observing \(y\) passes among \(n\) movies is:
\[
P(Y = y \mid p) = {n \choose y} p^{y}(1 - p)^{n - y}
\]
Here, \({n \choose y}\) represents the number of ways that \(y\) passing movies can occur among \(n\) movies.
Once the data have been observed, \(y\) and \(n\) are fixed. We then examine the expression as a function of the unknown \(p\). This creates the likelihood:
\[
L(p \mid y) = {n \choose y}\, p^{y}(1 - p)^{n - y}
\]
For 9 passes among 20 movies:
\[
L(p \mid y) = {20 \choose 9}\, p^{9}(1 - p)^{11}
\]
The value \(C(20, 9)\) does not change when \(p\) changes. It affects the height of the likelihood curve, but not its shape or the location of its maximum. Therefore, we can write:
\[
L(p \mid y) \propto p^{9}(1 - p)^{11}
\]
The likelihood asks:
Which possible values of \(p\) make the observed result of 9 passes and 11 failures relatively plausible?
Values close to 0.45 receive the greatest likelihood support. Values close to 0 or 1 receive very little support because they make a mixed result of 9 passes and 11 failures unlikely.
However, the likelihood is not automatically a probability distribution for \(p\). It allows us to compare parameter values, but it does not yet allow us to say that there is a certain probability that \(p\) lies in an interval.
Move the slider for \(p\) across the likelihood curve. The graph reports the relative likelihood of that value and compares it with \(p = 0.45\), the value receiving the greatest support.


// slider for a proposed value of the unknown proportion p
viewof p = Inputs.range([0, 1], {
  label: "p",
  value: 0.45,
  step: 0.01
})







// relative likelihood of 9 passes and 11 failures
{
  const mle = 0.45;

  // Kernel of L(p | y) for y = 9 and n = 20. The binomial coefficient
  // is constant in p, so it cancels in the relative likelihood.
  function kernel(x) {
    return (x ** 9) * ((1 - x) ** 11);
  }

  const peak = kernel(mle);
  const curve = Array.from({length: 401}, (_, i) =&gt; {
    const x = i / 400;
    return {p: x, relative: kernel(x) / peak};
  });

  const selected = kernel(p) / peak;
  const share = selected * 100;
  const shareText = share &gt;= 1
    ? `${share.toFixed(1)}%`
    : share &gt;= 0.01
      ? `${share.toFixed(2)}%`
      : share &gt; 0
        ? "&lt; 0.01%"
        : "0%";
  const relText = selected &gt;= 0.001
    ? selected.toFixed(3)
    : selected &gt; 0
      ? "&lt; 0.001"
      : "0";
  const atPeak = Math.abs(p - mle) &lt; 0.0005;
  const readout = atPeak
    ? html`&lt;p class="binomial-readout"&gt;When &lt;em&gt;p&lt;/em&gt; = ${p.toFixed(2)}, the relative likelihood is &lt;strong&gt;${relText}&lt;/strong&gt;. This is the value with the greatest support.&lt;/p&gt;`
    : html`&lt;p class="binomial-readout"&gt;When &lt;em&gt;p&lt;/em&gt; = ${p.toFixed(2)}, the relative likelihood is &lt;strong&gt;${relText}&lt;/strong&gt;. That is ${shareText} of the support at &lt;em&gt;p&lt;/em&gt; = 0.45.&lt;/p&gt;`;

  const plot = Plot.plot({
    width: Math.max(280, width - 4),
    height: 360,
    marginTop: 16,
    marginRight: 16,
    marginBottom: 48,
    marginLeft: 52,
    x: {
      label: "Population proportion, p",
      domain: [0, 1],
      ticks: [0, 0.2, 0.4, 0.6, 0.8, 1]
    },
    y: {
      label: null,
      grid: true,
      domain: [0, 1],
      ticks: [0, 0.25, 0.5, 0.75, 1]
    },
    marks: [
      Plot.areaY(curve, {
        x: "p",
        y: "relative",
        fill: "#2c3140",
        fillOpacity: 0.12,
        curve: "linear"
      }),
      Plot.line(curve, {
        x: "p",
        y: "relative",
        stroke: "#2c3140",
        strokeWidth: 2.25
      }),
      Plot.ruleX([mle], {
        stroke: "#5c5660",
        strokeDasharray: "4,3"
      }),
      Plot.ruleX([p], {
        stroke: "#b32b2f",
        strokeWidth: 2
      }),
      Plot.dot([{p, relative: selected}], {
        x: "p",
        y: "relative",
        fill: "#b32b2f",
        r: 5,
        title: d =&gt; `p = ${d.p.toFixed(2)}\nRelative likelihood = ${d.relative.toFixed(3)}`
      }),
      Plot.ruleY([0])
    ],
    style: {
      background: "transparent",
      color: "#15151E",
      fontFamily: "Helvetica, sans-serif",
      fontSize: "13px"
    }
  });

  return html`&lt;div class="binomial-figure"&gt;
    &lt;p class="binomial-ylabel"&gt;Relative likelihood&lt;/p&gt;
    ${plot}
    ${readout}
    &lt;p class="binomial-legend"&gt;&lt;span class="swatch swatch-observed"&gt;&lt;/span&gt; Proposed value of &lt;em&gt;p&lt;/em&gt; &lt;span class="swatch swatch-other"&gt;&lt;/span&gt; Likelihood curve &lt;span class="swatch swatch-max"&gt;&lt;/span&gt; Greatest support, &lt;em&gt;p&lt;/em&gt; = 0.45&lt;/p&gt;
  &lt;/div&gt;`;
}

The three posterior means are:

Beta(3, 7) prior gives a Beta(12, 18) posterior, with mean 0.40.
Beta(1, 1) prior gives a Beta(10, 12) posterior, with mean 0.455.
Beta(7, 3) prior gives a Beta(16, 14) posterior, with mean 0.533.

Their probabilities that \(p\) is below 0.50 are also different:

Under Beta(12, 18): \(P(p &lt; 0.50 \mid y) \approx 0.868\)
Under Beta(10, 12): \(P(p &lt; 0.50 \mid y) \approx 0.668\)
Under Beta(16, 14): \(P(p &lt; 0.50 \mid y) \approx 0.356\)

The lower-pass analysis suggests that \(p\) is probably below 0.50.
The neutral analysis also leans below 0.50, but the evidence is less decisive.
The higher-pass analysis leans the other way. Its posterior mean is 0.533, so about 64.4% of that posterior lies above 0.50. That is a tilt toward a higher pass rate, not a strong conclusion that \(p\) exceeds one half.
All three analysts observed the same movies. Their conclusions differ because 20 observations are not enough to overwhelm different prior beliefs.
This is why prior sensitivity analysis matters. A Bayesian analysis should not hide the effect of the prior. It should examine whether reasonable alternatives lead to substantially different conclusions.
If the conclusion remains stable across multiple defensible priors, it is relatively robust. If the conclusion changes, the honest conclusion may be that the current data are not strong enough to settle the question.
The three curves are the posteriors after the same 9 passes and 11 failures. The vertical line marks \(p = 0.50\).


// Three posteriors after 9 passes and 11 failures, and P(p &lt; 0.50 | y)
{
  const passes = 9;
  const failures = 11;
  const priors = [
    {name: "Lower-pass", alpha: 3, beta: 7, stroke: "#2c3140"},
    {name: "Neutral", alpha: 1, beta: 1, stroke: "#5c5660", dash: "4,3"},
    {name: "Higher-pass", alpha: 7, beta: 3, stroke: "#b32b2f"}
  ];

  function logGamma(z) {
    const c = [
      0.99999999999980993,
      676.5203681218851,
      -1259.1392167224028,
      771.32342877765313,
      -176.61502916214059,
      12.507343278686905,
      -0.13857109526572012,
      9.9843695780195716e-6,
      1.5056327351493116e-7
    ];
    if (z &lt; 0.5) return Math.log(Math.PI / Math.sin(Math.PI * z)) - logGamma(1 - z);
    z -= 1;
    let x = c[0];
    for (let i = 1; i &lt; c.length; i++) x += c[i] / (z + i);
    const t = z + 7.5;
    return 0.5 * Math.log(2 * Math.PI) + (z + 0.5) * Math.log(t) - t + Math.log(x);
  }

  function betaDensity(x, a, b) {
    if (!(x &gt; 0 && x &lt; 1)) return 0;
    const logB = logGamma(a) + logGamma(b) - logGamma(a + b);
    const density = Math.exp((a - 1) * Math.log(x) + (b - 1) * Math.log(1 - x) - logB);
    return Number.isFinite(density) ? density : 0;
  }

  function betaCDF(x, a, b) {
    if (x &lt;= 0) return 0;
    if (x &gt;= 1) return 1;
    const total = a + b - 1;
    let sum = 0;
    for (let k = a; k &lt;= total; k++) {
      let logCoefficient = 0;
      for (let i = 0; i &lt; k; i++) logCoefficient += Math.log(total - i) - Math.log(i + 1);
      sum += Math.exp(logCoefficient + k * Math.log(x) + (total - k) * Math.log(1 - x));
    }
    return Math.min(1, Math.max(0, sum));
  }

  function betaCurve(a, b) {
    return Array.from({length: 201}, (_, i) =&gt; {
      const p = i / 200;
      const x = Math.min(1 - 1e-6, Math.max(1e-6, p));
      return {p, density: betaDensity(x, a, b)};
    });
  }

  const curves = priors.map(prior =&gt; {
    const postAlpha = prior.alpha + passes;
    const postBeta = prior.beta + failures;
    return {
      ...prior,
      postAlpha,
      postBeta,
      mean: postAlpha / (postAlpha + postBeta),
      belowHalf: betaCDF(0.5, postAlpha, postBeta),
      curve: betaCurve(postAlpha, postBeta)
    };
  });

  const plot = Plot.plot({
    width: Math.max(280, width - 4),
    height: 360,
    marginTop: 16,
    marginRight: 16,
    marginBottom: 48,
    marginLeft: 52,
    x: {
      label: "Population proportion, p",
      domain: [0, 1],
      ticks: [0, 0.2, 0.4, 0.6, 0.8, 1]
    },
    y: {label: null, grid: true, nice: true},
    marks: [
      ...curves.map(d =&gt; Plot.line(d.curve, {
        x: "p",
        y: "density",
        stroke: d.stroke,
        strokeWidth: 2.25,
        strokeDasharray: d.dash
      })),
      Plot.ruleX([0.5], {stroke: "#8a837c"}),
      Plot.ruleY([0])
    ],
    style: {
      background: "transparent",
      color: "#15151E",
      fontFamily: "Helvetica, sans-serif",
      fontSize: "13px"
    }
  });

  const bits = curves.map(d =&gt; `${d.name} ${ (d.belowHalf * 100).toFixed(1) }%`);

  return html`&lt;div class="binomial-figure"&gt;
    &lt;p class="binomial-ylabel"&gt;Density&lt;/p&gt;
    ${plot}
    &lt;p class="binomial-readout"&gt;The posterior probability that &lt;em&gt;p&lt;/em&gt; is below 0.50 is &lt;strong&gt;${bits[0]}&lt;/strong&gt;, &lt;strong&gt;${bits[1]}&lt;/strong&gt;, and &lt;strong&gt;${bits[2]}&lt;/strong&gt;.&lt;/p&gt;
    &lt;p class="binomial-legend"&gt;&lt;span class="swatch swatch-other" style="margin-left:0"&gt;&lt;/span&gt; Lower-pass &lt;span class="swatch swatch-max"&gt;&lt;/span&gt; Neutral &lt;span class="swatch swatch-observed"&gt;&lt;/span&gt; Higher-pass&lt;/p&gt;
  &lt;/div&gt;`;
}

