    &lt;p class="binomial-legend"&gt;&lt;span class="swatch swatch-other" style="margin-left:0"&gt;&lt;/span&gt; Prior &lt;span class="swatch swatch-observed"&gt;&lt;/span&gt; Data, and the posterior mean&lt;/p&gt;
  &lt;/div&gt;`;
}

