    : "";

  return html`&lt;div class="binomial-figure"&gt;
    &lt;p class="binomial-ylabel"&gt;Density&lt;/p&gt;
    ${density}
    ${trace}
    &lt;p class="binomial-readout"&gt;After &lt;strong&gt;${revealed}&lt;/strong&gt; movies, the distribution is Beta(${alpha}, ${beta}), with mean &lt;strong&gt;${formatMean(mean)}&lt;/strong&gt;. Revealed outcomes: ${outcomeText}.${done}&lt;/p&gt;
    &lt;p class="binomial-legend"&gt;&lt;span class="swatch swatch-other" style="margin-left:0"&gt;&lt;/span&gt; Current distribution &lt;span class="swatch swatch-observed"&gt;&lt;/span&gt; Posterior mean &lt;span class="swatch swatch-band"&gt;&lt;/span&gt; One standard deviation&lt;/p&gt;
  &lt;/div&gt;`;
